import matplotlib

matplotlib.use("Agg")

import matplotlib.pyplot as plt
import pandas as pd

RC_PARAMS = {
    "font.size": 9,
    "axes.labelsize": 9,
    "axes.titlesize": 9,
    "xtick.labelsize": 8,
    "ytick.labelsize": 8,
    "legend.fontsize": 8,
    "axes.linewidth": 0.8,
    "xtick.major.width": 0.8,
    "ytick.major.width": 0.8,
}

FIGSIZE = (3.4, 2.6)
PALETTE = ["#0072B2", "#D55E00", "#009E73", "#CC79A7", "#E69F00", "#56B4E9", "#8C564B", "#000000"]
MUTED = "#bdbdbd"

DATA_PATH = "data/benchmarks.csv"
X_FIELD = "latency_ms"
Y_FIELD = "accuracy"
GROUP = "model"
SERIES_ORDER = ["baseline", "+augment", "+distill", "ours"]
EMPHASIS = "ours"
STEM = "06-accuracy-vs-latency"
FORMATS = ["png", "svg", "pdf"]
DPI = 600


def load():
    return pd.read_csv(DATA_PATH)


def series_names(frame):
    if SERIES_ORDER is not None:
        return list(SERIES_ORDER)
    return sorted(frame[GROUP].dropna().unique().tolist(), key=str)


def series_style(name, index):
    colour = PALETTE[index % len(PALETTE)]
    if EMPHASIS is None:
        return {"colour": colour, "size": 18, "zorder": 2}
    if name == EMPHASIS:
        return {"colour": colour, "size": 30, "zorder": 3}
    return {"colour": MUTED, "size": 12, "zorder": 1}


def draw(ax, df):
    names = series_names(df)
    for index, name in enumerate(names):
        frame = df[df[GROUP] == name]
        style = series_style(name, index)
        ax.scatter(
            frame[X_FIELD],
            frame[Y_FIELD],
            label=str(name),
            color=style["colour"],
            s=style["size"],
            zorder=style["zorder"],
        )


def finish(fig, ax):
    ax.set_xlabel("Latency (ms)")
    ax.set_ylabel("Top-1 accuracy (%)")
    ax.set_title("Accuracy against cost")
    ax.grid(False)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    ax.legend(
        title=None,
        frameon=False,
        loc="lower right",
    )
    fig.tight_layout()


def main():
    df = load()
    with plt.rc_context(RC_PARAMS):
        fig, ax = plt.subplots(figsize=FIGSIZE)
        draw(ax, df)
        finish(fig, ax)
        for fmt in FORMATS:
            path = f"{STEM}.{fmt}"
            kwargs = {"bbox_inches": "tight"}
            if fmt == "png":
                kwargs["dpi"] = DPI
            fig.savefig(path, **kwargs)
            print(f"wrote {path}")
    plt.close(fig)


if __name__ == "__main__":
    main()
